using System;using System.IO;using System.Collections;using System.Linq;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class CatchVisualProbe:MonoBehaviour{
 string folder;int failures;WatchDemoController w;ScareKit kit;GameObject root;Camera cam;
 public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Catch visual probe").AddComponent<CatchVisualProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 void Check(bool ok,string text){File.AppendAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+text+"\n");if(!ok)failures++;}
 void Capture(string name){var rt=new RenderTexture(1100,850,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var t=new Texture2D(1100,850,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1100,850),0,0);t.Apply();File.WriteAllBytes(folder+"/"+name+".png",t.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;Destroy(t);Destroy(rt);}
 IEnumerator Go(){w=FindAnyObjectByType<WatchDemoController>();var t=HorrorTuning.Current;var rig=FindAnyObjectByType<XROrigin>();foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality"))b.enabled=false;var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;Vector3 feet=new Vector3(0,0,-6.5f),eye=feet+Vector3.up*1.65f;rig.MoveCameraToWorldLocation(eye);rig.Camera.transform.rotation=Quaternion.LookRotation(Vector3.forward);Physics.SyncTransforms();
 root=new GameObject("Lunge review root");kit=new ScareKit(root.transform);var c=new ScareSequenceState(t);c.Begin(3,feet+Vector3.forward*.75f);for(int i=0;i<200&&c.Beat!=ScareBeat.Escape;i++)c.Tick(.1f,true,true,0,0);kit.Present(c,eye);var body=root.transform.Find("Scripted scare kit/Nightmare child");var renderer=body.GetComponent<Renderer>();
 var flash=FindObjectsByType<WatchLantern>(FindObjectsSortMode.None).First(x=>x.Slot==0);flash.transform.SetPositionAndRotation(eye+new Vector3(.15f,-.22f,0),Quaternion.LookRotation((feet+Vector3.up*1.1f+Vector3.forward*1.4f)-(eye+new Vector3(.15f,-.22f,0))));w.State.CycleLantern(0);yield return new WaitForSeconds(.2f);
 cam=new GameObject("Lunge review camera").AddComponent<Camera>();cam.enabled=false;cam.fieldOfView=65;cam.nearClipPlane=.04f;cam.transform.SetPositionAndRotation(eye,Quaternion.LookRotation((feet+Vector3.up*1.1f+Vector3.forward*1.4f)-eye));
 Check(c.Catch(1,feet),"Catch frame accepted for one of two keepers");kit.Present(c,eye);yield return new WaitForSeconds(.08f);kit.Present(c,eye);var first=body.position;float distance=Vector3.Distance(eye,renderer.bounds.ClosestPoint(eye));Check(renderer.enabled&&distance>=.5f,"Lunge begins visible outside half-metre face clearance ("+distance.ToString("F2")+" m)");
 yield return new WaitForSeconds(.09f);kit.Present(c,eye);distance=Vector3.Distance(eye,renderer.bounds.ClosestPoint(eye));Check(renderer.enabled&&distance>=.5f,"Lunge stays outside half-metre face clearance ("+distance.ToString("F2")+" m)");Check(Vector3.Distance(first,body.position)>.08f,"Body moves toward the caught keeper during the lunge");Capture("lunge-close");
 yield return new WaitForSeconds(.25f);kit.Present(c,eye);Check(!renderer.enabled,"Close lunge disappears after the brief effect");File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");kit.Dispose();Destroy(root);Destroy(cam.gameObject);Destroy(gameObject);
 }
}
